import{_ as t,a,o as r,a6 as d}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Sections","description":"","frontmatter":{"outline":false,"apiType":"graphql"},"headers":[],"relativePath":"api/graphql-api/admin/appearance/sections/index.md","filePath":"api/graphql-api/admin/appearance/sections/index.md","lastUpdated":1789385991000}'),i={name:"api/graphql-api/admin/appearance/sections/index.md"};function n(o,e,s,p,c,h){return r(),a("div",null,e[0]||(e[0]=[d('<h1 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h1><p>A section is one block of a storefront page. Each belongs to one theme and one channel, carries content per locale, and is drawn in the order the channel gives it.</p><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>What it draws</th></tr></thead><tbody><tr><td><code>image_carousel</code></td><td>A slider of images, each with its own link.</td></tr><tr><td><code>product_carousel</code></td><td>Products chosen by a filter, drawn as a slider.</td></tr><tr><td><code>category_carousel</code></td><td>Categories chosen by a filter, drawn as a slider.</td></tr><tr><td><code>footer_links</code></td><td>The footer link columns.</td></tr><tr><td><code>static_content</code></td><td>Free HTML and CSS.</td></tr><tr><td><code>services_content</code></td><td>The service badges strip, each with an icon.</td></tr></tbody></table><p>The type decides the fields a section carries. <a href="/api/graphql-api/admin/appearance/sections/fields.html">adminAppearanceSectionFields</a> returns that field set as a schema together with the values currently held, which is enough to build an editor without hard-coding any type.</p><h2 id="two-rules-the-storefront-depends-on" tabindex="-1">Two rules the storefront depends on <a class="header-anchor" href="#two-rules-the-storefront-depends-on" aria-label="Permalink to &quot;Two rules the storefront depends on&quot;">​</a></h2><ul><li><strong>One footer per channel.</strong> A channel can hold at most one <code>footer_links</code> section; creating a second, or switching another section to that type, is rejected with <code>422</code>.</li><li><strong>The footer is drawn last.</strong> A reorder that places <code>footer_links</code> anywhere but the end has it moved back, and the response returns the order that was actually stored.</li></ul><h2 id="staged-edits" tabindex="-1">Staged edits <a class="header-anchor" href="#staged-edits" aria-label="Permalink to &quot;Staged edits&quot;">​</a></h2><p>Nothing a client writes through the draft endpoints reaches shoppers until it is published:</p><table tabindex="0"><thead><tr><th>Staged</th><th>Endpoint</th><th>Held in</th></tr></thead><tbody><tr><td>Content, per locale</td><td><a href="/api/graphql-api/admin/appearance/sections/draft.html">createAdminAppearanceSectionDraft</a></td><td><code>draftOptions</code> on the translation</td></tr><tr><td>On/off</td><td><a href="/api/graphql-api/admin/appearance/sections/status.html">createAdminAppearanceSectionStatus</a></td><td><code>draftStatus</code></td></tr><tr><td>Render order</td><td><a href="/api/graphql-api/admin/appearance/sections/reorder.html">createAdminAppearanceSectionReorder</a></td><td><code>draftSortOrder</code></td></tr></tbody></table><p><code>hasDraft</code> on a section is <code>true</code> while any of the three is set. <a href="/api/graphql-api/admin/appearance/sections/publish.html">createAdminAppearanceSectionPublish</a> promotes every staged edit of a theme and channel at once; <a href="/api/graphql-api/admin/appearance/sections/discard.html">createAdminAppearanceSectionDiscard</a> throws them all away. <a href="/api/graphql-api/admin/appearance/sections/preview.html">adminAppearanceSectionPreview</a> returns the theme as those staged edits would leave it.</p><p>Creating a section stages it switched off, so an unbuilt section is never shown. Writing published values directly — without the draft cycle — is what <a href="/api/graphql-api/admin/appearance/sections/update.html">updateAdminAppearanceSection</a> does.</p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><p>Images and videos are uploaded through the REST endpoint <a href="/api/rest-api/admin/appearance/sections/media.html">Upload media</a> — a binary upload cannot be carried over GraphQL — which returns a stored path. The client then records that path in the section&#39;s options through the draft or update endpoint. Uploading does not change what a section shows.</p><h2 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Purpose</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/appearance/sections/list.html">adminAppearanceSections</a></td><td>Sections of a theme and channel, in render order</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/detail.html">adminAppearanceSection</a></td><td>One section with its translations</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/create.html">createAdminAppearanceSection</a></td><td>Add a section</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/update.html">updateAdminAppearanceSection</a></td><td>Write published values</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/delete.html">deleteAdminAppearanceSection</a></td><td>Remove a section</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/draft.html">createAdminAppearanceSectionDraft</a></td><td>Hold options as a draft</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/status.html">createAdminAppearanceSectionStatus</a></td><td>Stage on/off</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/reorder.html">createAdminAppearanceSectionReorder</a></td><td>Stage render order</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/duplicate.html">createAdminAppearanceSectionDuplicate</a></td><td>Copy a section</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/publish.html">createAdminAppearanceSectionPublish</a></td><td>Promote staged edits</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/discard.html">createAdminAppearanceSectionDiscard</a></td><td>Throw staged edits away</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/fields.html">adminAppearanceSectionFields</a></td><td>Field schema and current options</td></tr><tr><td><a href="/api/graphql-api/admin/appearance/sections/preview.html">adminAppearanceSectionPreview</a></td><td>Theme with staged edits applied</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Permission</th></tr></thead><tbody><tr><td>Read, fields, preview</td><td><code>appearance.sections</code></td></tr><tr><td>Create, copy</td><td><code>appearance.sections.create</code></td></tr><tr><td>Update, draft, status, order, publish, discard</td><td><code>appearance.sections.edit</code></td></tr><tr><td>Delete</td><td><code>appearance.sections.delete</code></td></tr></tbody></table>',18)]))}const f=t(i,[["render",n]]);export{m as __pageData,f as default};
